/* Example of basic screen styles */
body {
    background-color: #f0f0f0;
    font-family: Arial, sans-serif;
}
header {
    background-color: #333;
    color: white;
    padding: 1rem;
}
p {
    font-size: 1rem;
    line-height: 1.5;
}

/* Example: media query for print */
@media print {
  /* Print-specific styles go here */
}

/* Example: hide a sidebar for printing */
@media print {
    .sidebar {
        display: none;
    }
}

/* Example: setting font size for print */
@media print {
    body {
        font-size: 12pt;
    }
}

